//! Icons: lucide (ISC licence, <https://lucide.dev>) as inline SVG, 24 grid, stroke 2, round caps
//! and joins, `currentColor`.
//!
//! Every glyph is drawn as ONE `<path>` (see `paths.rs`, generated by `generate.mjs` from the
//! lucide package). That keeps the element tree of every icon identical, which matters here: the
//! islands router patches the server's next page into the DOM by walking old and new trees in
//! lockstep, so two different icons in the same spot (a theme toggle, a badge) must differ only
//! in an attribute, never in their children.
//!
//! Regenerate after adding names (`node crates/app/src/components/icons/generate.mjs
//! <lucide-react>/dist/esm/icons crates/app/src/components/icons/paths.rs <names…>`).

mod paths;

pub use paths::{NAMES, path};

use leptos::prelude::*;

/// An icon name: a literal (`"search"`) or data (`category.icon.clone()`, `&category.icon`).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct IconName(Oco<'static, str>);

impl IconName {
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl From<&'static str> for IconName {
    fn from(s: &'static str) -> Self {
        IconName(Oco::Borrowed(s))
    }
}
impl From<&'static mut str> for IconName {
    fn from(s: &'static mut str) -> Self {
        IconName(Oco::Borrowed(s))
    }
}
impl From<String> for IconName {
    fn from(s: String) -> Self {
        IconName(Oco::from(s))
    }
}
impl From<&String> for IconName {
    fn from(s: &String) -> Self {
        IconName(Oco::from(s.clone()))
    }
}
impl From<Oco<'static, str>> for IconName {
    fn from(s: Oco<'static, str>) -> Self {
        IconName(s)
    }
}

/// An inline lucide icon. `aria-hidden` unless `label` is given (then it is announced as an
/// image with that name). An unknown name draws `package`, so a typo never breaks a page.
#[component]
pub fn Icon(
    /// A lucide name, e.g. `"shopping-bag"`, or a `String` from data (no need to leak it).
    #[prop(into)]
    name: IconName,
    /// Rendered size in px (default 20). CSS can still resize it via `.icon`.
    #[prop(optional)]
    size: Option<u16>,
    #[prop(optional, into)] class: String,
    /// Accessible name; leave empty for decorative icons next to text.
    #[prop(optional)]
    label: Option<&'static str>,
) -> impl IntoView {
    let d = path(name.as_str())
        .or_else(|| path("package"))
        .unwrap_or_default();
    let size = size.unwrap_or(20);
    let class = if class.is_empty() {
        "icon".to_owned()
    } else {
        format!("icon {class}")
    };
    view! {
        <svg
            class=class
            width=size
            height=size
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
            stroke-linecap="round"
            stroke-linejoin="round"
            aria-hidden=label.is_none().then_some("true")
            role=label.map(|_| "img")
            aria-label=label
            focusable="false"
        >
            <path d=d></path>
        </svg>
    }
}

/// Whether the kit ships an icon by this name (for data-driven names, e.g. category icons).
pub fn exists(name: &str) -> bool {
    path(name).is_some()
}
